// Last updated: January 2026

export interface MAPlan {
  id: string;
  contractId: string;
  planId: string;
  organizationName: string;
  planName: string;
  planType: 'HMO' | 'PPO' | 'PFFS' | 'HMO-POS' | 'Local PPO' | 'Regional PPO';
  snpType: 'D-SNP' | 'C-SNP' | 'I-SNP' | null;
  premium: number;
  deductible: number;
  moop: number;
  drugDeductible: number | null;
  starRating: number | null;
  benefits: PlanBenefits;
}

export interface PlanBenefits {
  pcpCopay: string;
  specialistCopay: string;
  inpatientCopay: string;
  outpatientCopay: string;
  emergencyCopay: string;
  urgentCareCopay: string;
  drugTier1: string;
  drugTier2: string;
  drugTier3: string;
  drugTier4: string;
  drugTier5: string;
  dental: { preventive: string; comprehensive: string | null; maxCoverage: number | null } | null;
  vision: { examCopay: string; eyewearAllowance: number | null } | null;
  hearing: { examCopay: string; aidAllowance: number | null } | null;
  otcAllowance: number | null;
  fitness: string | null;
  transportation: string | null;
  meals: string | null;
  telehealth: string | null;
}

export interface ServiceArea {
  contractId: string;
  planId: string;
  countyCode: string;
  countyName: string;
}

