// Helper functions
export function getPlansForCounty(countyCode: string): MAPlan[] {
  const planIds = SERVICE_AREAS
    .filter(sa => sa.countyCode === countyCode)
    .map(sa => `${sa.contractId}-${sa.planId}`);

  const uniquePlanIds = [...new Set(planIds)];
  return KENTUCKY_PLANS.filter(p => uniquePlanIds.includes(p.id));
}

export function getPlansForZip(zipCode: string): MAPlan[] {
  const county = getCountyFromZip(zipCode);
  if (!county) {
    // Default to Jefferson County (Louisville) if no match
    return getPlansForCounty('18550');
  }
  return getPlansForCounty(county.countyCode);
}

export function getCountyFromZip(zipCode: string): { countyCode: string; countyName: string } | null {
  // Kentucky ZIP code prefixes to county mapping (using correct FIPS codes)
  const zipPrefixes: Record<string, { code: string; name: string }> = {
    // Louisville area (Jefferson County)
    '400': { code: '18550', name: 'Jefferson' },
    '401': { code: '18550', name: 'Jefferson' },
    '402': { code: '18550', name: 'Jefferson' },
    // Lexington area (Fayette County)
    '403': { code: '18330', name: 'Fayette' },
    '404': { code: '18330', name: 'Fayette' },
    '405': { code: '18330', name: 'Fayette' },
    // Northern KY - Covington/Newport (Kenton County)
    '410': { code: '18580', name: 'Kenton' },
    // Bowling Green (Warren County)
    '421': { code: '18986', name: 'Warren' },
    // Owensboro (Daviess County)
    '423': { code: '18290', name: 'Daviess' },
    // Ashland (Boyd County - 411xx ZIPs, but 411 conflicts with Kenton so using 416)
    '416': { code: '18090', name: 'Boyd' },
    // Paducah (McCracken County)
    '420': { code: '18720', name: 'McCracken' },
    // Elizabethtown (Hardin County)
    '427': { code: '18460', name: 'Hardin' },
  };

  const prefix = zipCode.slice(0, 3);
  const match = zipPrefixes[prefix];
  if (match) {
    return { countyCode: match.code, countyName: match.name };
  }
  return null;
}

// Legacy exports for backwards compatibility
export const SAMPLE_PLANS = KENTUCKY_PLANS;
export const SAMPLE_SERVICE_AREAS = SERVICE_AREAS;
